import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop, State } from '@stencil/core';
import { FormSize, LimitedSeverity } from '../../types';
import { FocusHelper } from '../../utils/focus-helper';

/**
 * @slot default - default slot for the content of the radio-button
 */
@Component({
  tag: 'groupui-radio-button',
  styleUrl: 'radio-button.scss',
  shadow: true,
})
export class RadioButton {
  /**
   * marks a button as checked
   */
  @Prop({ reflect: true }) readonly checked: boolean = false;

  /**
   * deactivates the specific radio-button
   */
  @Prop({ reflect: true }) readonly disabled: boolean = false;

  /**
   * value of the radio-button which is never shown to the user and used to identify which radio-button is selected
   */
  @Prop({ reflect: true }) readonly value: string = Math.random().toString(36).substring(7);

  /**
   * severity of the radio-button
   */
  @Prop({ reflect: true }) readonly severity: LimitedSeverity = 'none';

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * sets the size of the radio-button
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  @State() radioButtonTabIndex: number = 0;

  @State() focusType: string = '';

  @Element() host: HTMLElement;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Space') {
      event.preventDefault();
    }
  }

  @Listen('keyup')
  handleSpace(event: KeyboardEvent) {
    if (event.code === 'Space') {
      this.host.click();
    }
    this.focusType = FocusHelper.onKeyUp(this.focusType, event);
  }

  @Listen('blur')
  onBlur() {
    this.focusType = FocusHelper.onBlur();
  }

  @Listen('click', { capture: true })
  onClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  componentWillLoad() {
    this.handleHostTabIndex();
  }

  private handleHostTabIndex = () => {
    const tabIndex = this.host.getAttribute('tabIndex');
    if (tabIndex) {
      this.host.removeAttribute('tabIndex');
      this.radioButtonTabIndex = Number(tabIndex);
    }

    if (this.disabled) {
      this.radioButtonTabIndex = -1;
    }
  };

  private slotContainsText() {
    return this.host.textContent.trim().length > 0;
  }

  render() {
    return (
      <Host
        role="radio"
        aria-checked={this.checked ? 'true' : 'false'}
        aria-disabled={this.disabled ? 'true' : null}
        aria-labelledby="label"
        tabIndex={this.radioButtonTabIndex}
      >
        <div
          id="container"
          class={{
            disabled: this.disabled,
          }}
        >
          <div
            id="radio-button"
            class={{
              'radio-circle': true,
              checked: this.checked,
              keyboardFocus: this.focusType === 'keyboard',
              mouseFocus: this.focusType === 'mouse',
            }}
          />
          {this.slotContainsText() && (
            <div id="label">
              <slot></slot>
            </div>
          )}
        </div>
      </Host>
    );
  }
}
